def _workspace_patch(before: Path, after: Path) -> str:
    excluded_parts = {".git", ".lake", "__pycache__", "artifacts", "home"}
    paths = sorted(
        {p.relative_to(before) for p in before.rglob("*") if p.is_file()}
        | {p.relative_to(after) for p in after.rglob("*") if p.is_file()}
    )
    chunks: list[str] = []
    for relative in paths:
        if any(part in excluded_parts for part in relative.parts):
            continue
        old = before / relative
        new = after / relative
        old_bytes = old.read_bytes() if old.exists() else b""
        new_bytes = new.read_bytes() if new.exists() else b""
